101:			compactCodexResults(uses, exitByCall, failedByCall)
102:		}
103:		obj := record.obj // nil for a format line, which matches no case below
104:		switch jsonString(obj["type"]) {
105:		case "response_item":
106:			p := jsonMap(obj["payload"])
107:			switch jsonString(p["type"]) {
108:			case "function_call":
109:				name := normalizeToolName(jsonString(p["name"]))
110:				tools = append(tools, corpusToolOp{name: name, line: ln})
111:				if cmd := shellCommandFromInput(name, p["arguments"]); cmd != "" {
