113:						commands = append(commands, corpusCommand{head: h, raw: cmd, line: ln, callID: jsonString(p["call_id"])})
114:					}
115:				}
116:			case "custom_tool_call":
117:				name := normalizeToolName(jsonString(p["name"]))
118:				tools = append(tools, corpusToolOp{name: name, line: ln})
119:				files = append(files, patchFiles(jsonString(p["input"]), ln)...)
120:			case "function_call_output", "custom_tool_call_output":
121:				if id := jsonString(p["call_id"]); id != "" {
122:					if code, ok := parseExitCode(jsonString(p["output"])); ok {
123:						exitByCall[id] = code
124:					}
125:				}
126:			case "patch_apply_end":
127:				if id := jsonString(p["call_id"]); id != "" {
128:					if code, ok := parseExitCode(jsonString(p["stdout"])); ok {
