145:			c := code
146:			commands[i].exitCode = &c
147:			commands[i].failed = code != 0
148:		} else if failedByCall[commands[i].callID] {
149:			commands[i].failed = true
150:		}
151:	}
152:	return tools, commands, dedupeFileRefs(files)
